parameters.jsCode:
const research = $json.output;
const forecast = $('Create Forecast Record').item.json;

return {
  json: {
    forecast_id: forecast.id,

    research: research,

    jev_request: {
      model: "typesafe/jev",
      input: {
        state: JSON.stringify({
          proposition: research.normalized_proposition,
          forecast_horizon: research.forecast_horizon,
          supporting_evidence: research.supporting_evidence,
          contradicting_evidence: research.contradicting_evidence,
          uncertainties: research.key_uncertainties,
          sources: research.sources_used
        }),
        questions: {
          outcome: {
            type: "noul",
            instructions: "Based on the research evidence, does the proposition occur?"
          },
          evidence_strength: {
            type: "score",
            instructions: "How strongly does the evidence support the proposition?",
            criteria: [
              "Strongly against",
              "Somewhat against",
              "Neutral or insufficient",
              "Somewhat supports",
              "Strongly supports"
            ]
          },
          evidence_quality: {
            type: "score",
            instructions: "How high is the overall quality of the evidence?",
            criteria: [
              "Very poor",
              "Poor",
              "Moderate",
              "Good",
              "Very good"
            ]
          },
          contradictory_evidence: {
            type: "noul",
            instructions: "Is there substantial evidence contradicting the proposition?"
          }
        }
      }
    }
  }
};

const jev = $json.result.result;
const answers = jev.answers;

// Get the preserved context from the node immediately before Jev
const prepared = $('Prepare Jev Request').item.json;

return {
  json: {
    forecast_id: prepared.forecast_id,

    proposition: prepared.research.normalized_proposition,
    forecast_horizon: prepared.research.forecast_horizon,

    research: prepared.research,

    prediction: answers.outcome.noul,

    evidence_strength: answers.evidence_strength.score,
    evidence_strength_confidence: answers.evidence_strength.confidence,

    evidence_quality: answers.evidence_quality.score,
    evidence_quality_confidence: answers.evidence_quality.confidence,

    contradictory_evidence: answers.contradictory_evidence.noul,

    jev_response: $json.result,

    jev_model: jev.model,
    jev_usage: jev.usage
  }
};

const result = $json;

const response = {
  request_id: result.id,
  question: result.question,
  proposition: result.research.normalized_proposition,

  prediction: Number(result.prediction),
  probability: Number(result.probability),

  evidence_strength: Number(result.evidence_strength),
  evidence_quality: Number(result.evidence_quality),

  contradictory_evidence: Number(
    result.jev_response.result.answers.contradictory_evidence.noul
  ),

  completed_at: result.completed_at,

  research: result.research
};

if (result.include_sources) {
  response.sources = result.sources || [];
}

return {
  json: response
};

