const forecast = $('Build Final Response').item.json;
const explanation = $json.content.parts[0].text;

const probability = Number(forecast.probability);
const probabilityPercent = Math.round(probability * 100);

let output = `Forecast:
${probabilityPercent}% probability

Analysis:
${explanation}`;

if (forecast.sources && forecast.sources.length > 0) {
  output += `\n\nSources:`;

  for (const source of forecast.sources) {
    const title = source.title || source.source_title || 'Source';
    const url = source.url || '';

    output += `\n• ${title}`;

    if (url) {
      output += `\n  ${url}`;
    }
  }
}

return {
  json: {
    output: output
  }
};
